package com.alsafa.native4;

import android.app.Activity;import android.text.InputType;import android.view.Gravity;import android.view.View;import android.view.ViewGroup;import android.widget.ArrayAdapter;import android.widget.Button;import android.widget.EditText;import android.widget.LinearLayout;import android.widget.Spinner;import android.widget.TextView;import com.alsafa.native4.core.AccountingChoices;import com.alsafa.native4.core.DirectRepairPartSaleStore;import com.alsafa.native4.core.Native4BackgroundSync;import com.alsafa.native4.core.Native4Services;import com.alsafa.native4.core.SplitPaymentStore;import java.util.ArrayList;import java.util.List;
/** Quick repair/part flow: hand the watch back now or leave it at AlSafa after the quick operation. */
public final class DirectPartSalePanelBinder {
 private final Activity a;private final Native4Services services;private final TextView status;private final LinearLayout panel,paymentRows,leaveDetails;private final EditText partId,quantity,unitPrice,serviceFee,customerName,customerPhone,watchNote;private final Spinner currency,handover;
 public DirectPartSalePanelBinder(Activity a,Native4Services services,TextView status,ViewGroup host){this.a=a;this.services=services;this.status=status;panel=new LinearLayout(a);panel.setOrientation(LinearLayout.VERTICAL);panel.setVisibility(View.GONE);TextView title=new TextView(a);title.setText("الصيانة السريعة / بيع قطعة");title.setTextSize(20);title.setGravity(Gravity.END);panel.addView(title);TextView help=new TextView(a);help.setText("مثال: بطارية، سير، زجاج أو خدمة سريعة. بعد العملية اختر هل استلم العميل الساعة فورًا أم تركها لدينا.");help.setGravity(Gravity.END);panel.addView(help);partId=field(a,"اسم / معرف / باركود قطعة الصيانة",InputType.TYPE_CLASS_TEXT);quantity=field(a,"الكمية",InputType.TYPE_CLASS_NUMBER);quantity.setText("1");unitPrice=field(a,"سعر القطعة",numType());serviceFee=field(a,"أجرة الخدمة (اختياري)",numType());currency=new Spinner(a);currency.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,AccountingChoices.CURRENCY_LABELS));panel.addView(partId);panel.addView(quantity);LinearLayout amountRow=new LinearLayout(a);amountRow.setOrientation(LinearLayout.HORIZONTAL);amountRow.setGravity(Gravity.CENTER_VERTICAL);amountRow.addView(unitPrice,new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,3f));amountRow.addView(currency,new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1f));panel.addView(amountRow);panel.addView(serviceFee);TextView handLabel=new TextView(a);handLabel.setText("حالة الساعة بعد الصيانة السريعة");handLabel.setGravity(Gravity.END);panel.addView(handLabel);handover=new Spinner(a);handover.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,new String[]{"تم التسليم — استلم العميل الساعة فورًا","ترك الساعة لدينا"}));panel.addView(handover);leaveDetails=new LinearLayout(a);leaveDetails.setOrientation(LinearLayout.VERTICAL);customerName=field(a,"اسم العميل",InputType.TYPE_CLASS_TEXT);customerPhone=field(a,"رقم الهاتف",InputType.TYPE_CLASS_PHONE);watchNote=field(a,"ملاحظة عن الساعة / سبب تركها",InputType.TYPE_CLASS_TEXT);leaveDetails.addView(customerName);leaveDetails.addView(customerPhone);leaveDetails.addView(watchNote);leaveDetails.setVisibility(View.GONE);panel.addView(leaveDetails);handover.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){leaveDetails.setVisibility(pos==1?View.VISIBLE:View.GONE);}public void onNothingSelected(android.widget.AdapterView<?> p){}});TextView paymentLabel=new TextView(a);paymentLabel.setText("الدفعات — مبلغ وعملة ومكان تحصيل لكل دفعة");paymentLabel.setGravity(Gravity.END);panel.addView(paymentLabel);paymentRows=new LinearLayout(a);paymentRows.setOrientation(LinearLayout.VERTICAL);panel.addView(paymentRows);Button add=new Button(a);add.setText("+ إضافة دفعة أخرى");add.setOnClickListener(v->addPaymentRow());panel.addView(add);addPaymentRow();Button save=new Button(a);save.setText("✓ تثبيت الصيانة السريعة");save.setMinHeight(dp(62));save.setOnClickListener(v->save());panel.addView(save);host.addView(panel);}
 public void show(boolean visible){panel.setVisibility(visible?View.VISIBLE:View.GONE);}
 private void addPaymentRow(){LinearLayout box=new LinearLayout(a);box.setOrientation(LinearLayout.VERTICAL);EditText amount=field(a,"المبلغ المقبوض",numType());Spinner cur=new Spinner(a);cur.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,AccountingChoices.CURRENCY_LABELS));Spinner account=new Spinner(a);account.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,new String[]{"الدرج","شام كاش","الخزنة الخارجية","البنك"}));Button remove=new Button(a);remove.setText("حذف الدفعة");remove.setOnClickListener(v->{if(paymentRows.getChildCount()>1)paymentRows.removeView(box);else amount.setText("");});box.addView(amount);box.addView(cur);box.addView(account);box.setTag(new PaymentViews(amount,cur,account));box.addView(remove);paymentRows.addView(box);}
 private List<SplitPaymentStore.Payment> readPayments(){List<SplitPaymentStore.Payment> out=new ArrayList<>();for(int i=0;i<paymentRows.getChildCount();i++){PaymentViews p=(PaymentViews)paymentRows.getChildAt(i).getTag();String raw=p.amount.getText().toString().trim();if(raw.isEmpty())continue;double amount=Double.parseDouble(raw);String cur=AccountingChoices.codeAt(AccountingChoices.CURRENCY_CODES,p.currency.getSelectedItemPosition());String acc=accountCode(p.account.getSelectedItemPosition());if("SHAM_CASH".equals(acc)&&"TRY".equals(cur))throw new IllegalArgumentException("شام كاش يقبل الدولار والليرة السورية فقط");String method="SHAM_CASH".equals(acc)?"SHAM_CASH":"CASH";out.add(new SplitPaymentStore.Payment(amount,cur,method,acc));}return out;}
 private void save(){try{boolean left=handover.getSelectedItemPosition()==1;String name=customerName.getText().toString().trim(),phone=customerPhone.getText().toString().trim(),note=watchNote.getText().toString().trim();if(left&&name.isEmpty())throw new IllegalArgumentException("اسم العميل مطلوب عند ترك الساعة لدينا");if(left&&phone.isEmpty())throw new IllegalArgumentException("رقم الهاتف مطلوب عند ترك الساعة لدينا");String pid=partId.getText().toString().trim();int q=Integer.parseInt(quantity.getText().toString().trim());double price=num(unitPrice),fee=num(serviceFee);String cur=AccountingChoices.codeAt(AccountingChoices.CURRENCY_CODES,currency.getSelectedItemPosition());List<SplitPaymentStore.Payment> payments=readPayments();DirectRepairPartSaleStore.Result r=services.directPartSales.sellSplit(pid,q,price,fee,cur,payments);Native4BackgroundSync.request(a);DeveloperDashboardPanelBinder.refreshActive();String handText=left?"ترك الساعة لدينا — "+name+" — "+phone+(note.isEmpty()?"":" — "+note):"تم التسليم للعميل فورًا";partId.setText("");quantity.setText("1");unitPrice.setText("");serviceFee.setText("");customerName.setText("");customerPhone.setText("");watchNote.setText("");handover.setSelection(0);paymentRows.removeAllViews();addPaymentRow();status.setText("✓ الصيانة السريعة: "+r.partName+" — "+fmt(r.total)+" "+r.currency+" — "+handText);}catch(Exception e){status.setText("لم تُحفظ الصيانة السريعة: "+msg(e));}}
 private static String accountCode(int p){if(p==1)return "SHAM_CASH";if(p==2)return "EXTERNAL";if(p==3)return "BANK";return "MAIN";}private static final class PaymentViews{final EditText amount;final Spinner currency,account;PaymentViews(EditText a,Spinner c,Spinner ac){amount=a;currency=c;account=ac;}}
 private static EditText field(Activity a,String hint,int type){EditText e=new EditText(a);e.setHint(hint);e.setInputType(type);e.setGravity(Gravity.END);e.setMinHeight(dpStatic(a,54));e.setLayoutParams(new ViewGroup.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT));return e;}private static int numType(){return InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL;}private static int dpStatic(Activity a,int v){return Math.round(v*a.getResources().getDisplayMetrics().density);}private int dp(int v){return dpStatic(a,v);}private static double num(EditText e){String s=e.getText().toString().trim();return s.isEmpty()?0:Double.parseDouble(s);}private static String fmt(double v){return String.format(java.util.Locale.US,"%.2f",v);}private static String msg(Exception e){return e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();}
}
